import sys; sys.path.insert(0,'/app/analysis')
from common import *
pd.set_option('display.width',300)
piv=load()
SUBS=['COOLING','PRIMARY_LOOP','CORE','STEAM_GEN','TURBINE']
mask={'COOLING_PRES_01':[('2024-01-15 23:55','2024-01-16 00:36')],
      'TURB_OUTPUT_01':[('2024-01-15 17:50','2024-01-15 19:10')],
      'STEAM_PRES_01':[('2024-01-15 19:50','2024-01-15 21:10')]}

def prep(mode):
    if mode=='diurnal':
        res,sd,_=fit_baseline(piv); z=res/sd
    else:  # local linear baseline on 20:00-23:30 Jan 15
        z=pd.DataFrame(index=piv.index,columns=piv.columns,dtype=float)
        for s in ORDER:
            y=piv[s].loc['2024-01-15 20:00':'2024-01-15 23:30'].dropna(); t=hours(y.index)
            X=np.column_stack([np.ones_like(t),t]); beta,*_=np.linalg.lstsq(X,y.values,rcond=None)
            r=y.values-X@beta; sd=1.4826*np.median(np.abs(r-np.median(r)))
            ta=hours(piv.index); z[s]=(piv[s].values-np.column_stack([np.ones_like(ta),ta])@beta)/sd
    zp={}
    for s in ORDER:
        d=int(meta.loc[s,'response_delay_minutes']); col=z[s].dropna(); col.index=col.index-pd.Timedelta(minutes=d); zp[s]=col
    zp=pd.DataFrame(zp)
    sign=np.sign(zp.loc['2024-01-16 04:00':'2024-01-16 06:00'].mean()); zs=zp*sign
    for s,ivs in mask.items():
        for a,b in ivs: zs.loc[a:b,s]=np.nan
    return zs

def joint(zs, frac, tstart='2024-01-15 20:00'):
    out={}
    for ss in SUBS:
        cols=[s for s in ORDER if meta.loc[s,'subsystem']==ss]
        ends={}
        for s in cols:
            x=zs[s].dropna(); plat=x.loc['2024-01-16 19:00':'2024-01-16 23:30'].median()
            r=x.rolling(15,center=True,min_periods=5).mean()
            ends[s]=r[(r.index>pd.Timestamp('2024-01-16 00:00'))&(r>frac*plat)].index[0]
        best=None
        for t0 in pd.date_range('2024-01-15 22:00','2024-01-16 02:30',freq='1min'):
            h0=hours(pd.DatetimeIndex([t0]))[0]; sse=0
            for s in cols:
                y=zs[s].loc[tstart:ends[s]].dropna(); t=hours(y.index)
                X=np.column_stack([np.ones_like(t), np.clip(t-h0,0,None)])
                beta,*_=np.linalg.lstsq(X,y.values,rcond=None); sse+=float(((y.values-X@beta)**2).sum())
            if best is None or sse<best[1]: best=(t0,sse)
        out[ss]=best[0]
    return out

def cusum(zs, k=0.5, h=15):
    """one-sided CUSUM on subsystem-combined z (physical time); onset = last time cusum was zero before crossing h"""
    out={}
    for ss in SUBS:
        cols=[s for s in ORDER if meta.loc[s,'subsystem']==ss]
        m=zs[cols].loc['2024-01-15 20:00':'2024-01-16 03:00']; n=m.notna().sum(axis=1); c=(m.mean(axis=1)*np.sqrt(n)).dropna()
        S=0; last0=c.index[0]
        for t,v in c.items():
            S=max(0,S+v-k)
            if S==0: last0=t
            if S>h: out[ss]=last0; break
    return out

for mode in ('diurnal','local_linear'):
    zs=prep(mode)
    for frac in (0.25,0.4,0.6):
        o=joint(zs,frac); print(f"hinge {mode:13s} end@{int(frac*100):2d}%: "+"  ".join(f"{k}={v.strftime('%H:%M')}" for k,v in o.items()),"  ORDER:",sorted(o,key=o.get))
    for h in (10,20,40):
        o=cusum(zs,h=h); print(f"cusum {mode:13s} h={h:2d}:      "+"  ".join(f"{k}={v.strftime('%H:%M')}" for k,v in o.items()),"  ORDER:",sorted(o,key=o.get))

# no delay correction at all, for reference
print("\nWithout delay correction (diurnal baseline):")
res,sd,_=fit_baseline(piv); z=res/sd
sign=np.sign(z.loc['2024-01-16 04:00':'2024-01-16 06:00'].mean()); zs=z*sign
for s,ivs in mask.items():
    for a,b in ivs: zs.loc[a:b,s]=np.nan
o=joint(zs,0.4); print("  "+"  ".join(f"{k}={v.strftime('%H:%M')}" for k,v in o.items()),"  ORDER:",sorted(o,key=o.get))

# the three isolated anomalies, raw values
print("\nIsolated anomalies (raw values, reported UTC time):")
for s,(a,b) in [('TURB_OUTPUT_01',('2024-01-15 17:55','2024-01-15 19:05')),('STEAM_PRES_01',('2024-01-15 19:55','2024-01-15 21:05')),('COOLING_PRES_01',('2024-01-16 00:05','2024-01-16 00:40'))]:
    x=piv[s].loc[a:b]
    print(f"{s}: ", " ".join(f"{t.strftime('%H:%M')}={v:.2f}" for t,v in x.items() if t.minute%5==0 or t in (x.index[0],x.index[-1])))
# do other sensors in same subsystem move during those windows?
res,sd,_=fit_baseline(piv); z=res/sd
for ss,(a,b) in [('TURBINE',('2024-01-15 18:00','2024-01-15 19:00')),('STEAM_GEN',('2024-01-15 20:00','2024-01-15 21:00')),('COOLING',('2024-01-16 00:10','2024-01-16 00:35'))]:
    cols=[s for s in ORDER if meta.loc[s,'subsystem']==ss]
    print(f"  {ss} mean z in window {a}..{b}:", z.loc[a:b,cols].mean().round(2).to_dict())
